<?php require 'includes/auth.php'; require_login(); require 'config/db.php'; include 'includes/header.php';
$q="SELECT i.*, COALESCE(SUM(CASE WHEN t.transaction_type='RECEIVED' THEN t.quantity ELSE 0 END),0) received, COALESCE(SUM(CASE WHEN t.transaction_type='ISSUED' THEN t.quantity ELSE 0 END),0) issued, COALESCE(SUM(CASE WHEN t.transaction_type='RETURNED' THEN t.quantity ELSE 0 END),0) returned FROM inventory_items i LEFT JOIN inventory_transactions t ON t.item_code=i.item_code GROUP BY i.id ORDER BY i.item_description"; $rs=$conn->query($q); ?>
<h3>Inventory</h3><div class="card p-4"><table class="table datatable"><thead><tr><th>Code</th><th>Description</th><th>Location</th><th>UOM</th><th>Received</th><th>Total Usage</th><th>Total Return</th><th>Total Stocks</th><th>Status</th><th>Action</th></tr></thead><tbody><?php while($r=$rs->fetch_assoc()): $status=$r['actual_stock']<=0?'Out of Stock':($r['actual_stock']<=$r['reorder_level']?'Low Stock':'Available'); ?><tr><td><?=htmlspecialchars($r['item_code'])?></td><td><?=htmlspecialchars($r['item_description'])?></td><td><?=htmlspecialchars($r['location'])?></td><td><?=htmlspecialchars($r['uom'])?></td><td><?=$r['received']?></td><td><?=$r['issued']?></td><td><?=$r['returned']?></td><td><b><?=$r['actual_stock']?></b></td><td><?=$status?></td><td><a class="btn btn-sm btn-primary" href="activity.php?code=<?=urlencode($r['item_code'])?>">View</a></td></tr><?php endwhile; ?></tbody></table></div><?php include 'includes/footer.php'; ?>
